def _component_06():
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        package_names = sorted(packages)
        best = [None, None]

        def acyclic(edges):
            active, done = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for dependency in edges.get(name, []):
                    if not visit(dependency):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(assigned, constraints):
            for name, version in assigned.items():
                if any(not low <= version <= high
                       for low, high in constraints.get(name, [])):
                    return

            unresolved = sorted(set(constraints) - set(assigned))
            if not unresolved:
                edges = {}
                for name, version in assigned.items():
                    row = next(row for row in packages[name]
                               if row["version"] == version)
                    edges[name] = [dep["name"] for dep in row.get("deps", [])
                                   if not dep.get("feature") or
                                   dep["feature"] in features]
                if not acyclic(edges):
                    return
                vector = tuple(assigned.get(name, -1) for name in package_names)
                if best[0] is None or vector < best[0]:
                    best[0] = vector
                    best[1] = dict(assigned)
                return

            name = unresolved[0]
            ranges = constraints[name]
            rows = sorted(packages.get(name, []), key=lambda row: row["version"])
            for row in rows:
                version = row["version"]
                if any(not low <= version <= high for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue

                next_assigned = dict(assigned)
                next_assigned[name] = version
                next_constraints = {key: list(value)
                                    for key, value in constraints.items()}
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    next_constraints.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"]))
                search(next_assigned, next_constraints)

        roots = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        search({}, roots)
        if best[1] is None:
            return {"error": "unsatisfiable"}
        return {"versions": best[1]}

    return solve


def _component_07():
    from itertools import combinations

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked:
            return {"error": "impossible"}

        options = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            intervals = sorted((job["start"], job["end"]) for job in subset)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue

            ordered_ids = tuple(sorted(ids))
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ordered_ids < best_ids)):
                best_value = value
                best_ids = ordered_ids

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << index for index, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        initial_mask = bits.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = (data["source"], data["coupons"], initial_mask)
        distances = {start: data["start"]}
        queue = [(data["start"], data["source"], data["coupons"], initial_mask)]

        while queue:
            arrival, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and remaining == 0 and mask == full_mask:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    choices.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                    remaining - 1))
                next_mask = mask | bits.get(edge["v"], 0)
                for duration, next_remaining in choices:
                    next_arrival = depart + duration
                    if next_arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_remaining, next_mask)
                    if next_arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = next_arrival
                        heapq.heappush(queue, (next_arrival, edge["v"],
                                               next_remaining, next_mask))
        return {"arrival": None}

    return solve


